local player = game.Players.LocalPlayer
local gui = Instance.new("ScreenGui", player:WaitForChild("PlayerGui"))
gui.Name = "hdadmin_gui_byshd0k1dd"
gui.ResetOnSpawn = false

-- ฟังก์ชันทำขอบ Rainbow
local function makeRainbowBorder(obj)
	task.spawn(function()
		local h = 0
		while obj and obj.Parent do
			obj.BorderColor3 = Color3.fromHSV(h, 1, 1)
			h = (h + 0.01) % 1
			wait(0.02)
		end
	end)
end

-- Frame GUI
local frame = Instance.new("Frame")
frame.Size = UDim2.new(0, 550, 0, 600)
frame.Position = UDim2.new(0.5, -275, 0.5, -300)
frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
frame.BorderSizePixel = 3
frame.Active = true
frame.Draggable = true
frame.Parent = gui
makeRainbowBorder(frame)

-- Title
local title = Instance.new("TextLabel", frame)
title.Size = UDim2.new(1, 0, 0, 40)
title.Position = UDim2.new(0, 0, 0, 0)
title.BackgroundTransparency = 1
title.Text = "d00lgui  f3x| by shd0"
title.TextColor3 = Color3.fromRGB(0, 162, 255)
title.Font = Enum.Font.GothamBold
title.TextScaled = true

-- ปุ่มที่ 1
local btn1 = Instance.new("TextButton", frame)
btn1.Name = "Button1"
btn1.Size = UDim2.new(0, 100, 0, 30)
btn1.Position = UDim2.new(0, 20, 0, 60)
btn1.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
btn1.TextColor3 = Color3.fromRGB(0, 162, 255)
btn1.Font = Enum.Font.Gotham
btn1.TextScaled = true
btn1.Text = "btools"
btn1.BorderSizePixel = 2
makeRainbowBorder(btn1)
btn1.MouseButton1Click:Connect(function()

	game.ReplicatedStorage.HDAdminHDClient.Signals.RequestCommand:InvokeServer(";btools")
end)

-- ปุ่มที่ 2
local btn2 = btn1:Clone()
