-- ฟังก์ชันสร้าง Part
local function createPart(data)
	local p = sync:Create("Part", {
		Size = data.Size,
		Position = data.Position,
		Anchored = true,
		Material = data.Material or Enum.Material.Plastic,
		Color = data.Color or Color3.new(1, 1, 1),
		Name = data.Name or "Part"
	})
	if data.DecalID then
		for _, face in ipairs(Enum.NormalId:GetEnumItems()) do
			sync:Create("Decal", {
				Face = face,
				Texture = "rbxassetid://" .. data.DecalID,
				Parent = p
			})
		end
	end
end

-- ฟังก์ชันสร้าง Mesh
local function createMesh(data)
	local p = sync:Create("Part", {
		Size = data.PartSize,
		Position = data.Position,
		Anchored = true,
		Name = data.Name or "MeshPart"
	})
	sync:Create("SpecialMesh", {
		MeshType = Enum.MeshType.FileMesh,
		MeshId = "rbxassetid://" .. data.MeshId,
		TextureId = data.Texture and "rbxassetid://" .. data.Texture or "",
		Scale = data.MeshSize,
		Parent = p
	})
end

